import kotlin.math.pow
import kotlin.random.Random
import kotlin.time.Duration
import kotlin.time.Duration.Companion.milliseconds
import kotlin.time.Duration.Companion.seconds

class RetryPolicy(
    private val maxAttempts: Int = 5,
    private val base: Duration = 500.milliseconds,
    private val cap: Duration = 30.seconds,
    private val random: Random = Random.Default,
) {
    fun delayFor(attempt: Int): Duration {
        val ceiling = minOf(cap, base * 2.0.pow(attempt))
        return (random.nextDouble() * ceiling.inWholeMilliseconds).toLong().milliseconds
    }

class RetryPolicyTest {
    private val maxRandom = object : Random() {
        override fun nextBits(bitCount: Int) = 0
        override fun nextDouble() = 1.0
    }

    @Test
    fun `delay grows exponentially`() {
        val p = RetryPolicy(random = maxRandom)
        assertEquals(listOf(500L, 1000L, 2000L, 4000L), (0..3).map { p.delayFor(it).inWholeMilliseconds })
    }

    @Test
    fun `delay never exceeds the cap`() {
        assertEquals(30_000L, RetryPolicy(random = maxRandom).delayFor(12).inWholeMilliseconds)
    }

    @Test
    fun `jitter stays within bounds`() {
        val p = RetryPolicy(random = Random(42))
        repeat(1_000) { assertTrue(p.delayFor(3).inWholeMilliseconds in 0L..4_000L) }
    }

